#!/usr/bin/env bash
. "${CLAUDE_PLUGIN_ROOT_CORE:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../../core" && pwd -P)}/hooks/lib/role-directive.sh"
YOU_DECIDE="YOU DECIDE: 이 스펙/처리가 법·규제를 통과하는가"
USE_WHEN="USE_WHEN: 개인정보·라이선스·계약이 걸릴 때"
PRODUCES=$'PRODUCES (required record fields): compliance verdict (one of pass / pass-with-mitigations / fail, derived from the graded risk ratings below), applicable regulation list (named, not generic), required mitigations (each mapped 1:1 to the risk/regulation-clause pair it addresses), risk rating per identified issue (graded red/amber/green, not binary)\n\nPHASE 1 (proposal) methodology, mechanically enforced by the legal-compliance-phase1-proposal-gate plugin: (i) state the spec/process under review and its scope boundary; (ii) enumerate candidate regulations by name and state exclusions; (iii) give a necessity/proportionality rationale before naming any mitigation (ordering, not just presence); (iv) an Evidence/rationale section citing, per adopted position, either a named regulation clause, a cited section of the reviewed spec, or an explicit "assumption, unsourced" label. A claim with no traceable source is an assumption, stated as one, never presented as a finding.\n\nPHASE 2 (record) methodology, mechanically enforced by the legal-compliance-phase2-record-gate plugin: named regulation/standard list; graded (red/amber/green) risk rating per identified issue; mitigations, each naming the specific risk/clause pair it addresses; final verdict (pass/pass-with-mitigations/fail) derived from the ratings above, never independent of them. No verdict may be entered that does not trace to a rating already stated in the same record.\n\nBOTH PHASES additionally: the legal-compliance-fanout-completeness-gate plugin enforces that any claimed multi-source/multi-angle survey shows at least two independently-attributed sources, not one restated.\n\nWRITE_SCOPE: []'
HAND_OFF=$'HAND-OFF: 전사 리스크 노출 규모 판단은 → risk-management\n\nBOUNDARY CASE: if the work in front of you drifts outside `decides` above,\nstop and hand off per the arrow — do not silently absorb another role\'s\nscope. Record the hand-off point in this role\'s record before opening the\nnext role\'s session.'
core_role_directive "$YOU_DECIDE" "$USE_WHEN" "$PRODUCES" "$HAND_OFF"
